[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "A shopper must not take a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "shelvesOnBothHorizontalSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shelvesOnBothVerticalSides": {
          "and": [
            "shelfN",
            "shelfS"
          ]
        },
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelvesOnBothHorizontalSides",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelvesOnBothVerticalSides",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
